<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iExchange { const RT_APPLICATION_XML_FHIR = 'application/xml+fhir', RT_APPLICATION_XML = 'application/xml', RT_APPLICATION_X_WWW_FORM_URLENCODED = 'application/x-www-form-urlencoded', RT_APPLICATION_JSON_FHIR = 'application/json+fhir', RT_APPLICATION_JSON = 'application/json'; const HTTP_GET = 'httpGET', HTTP_POST = 'httpPOST', HTTP_PUT = 'httpPUT', HTTP_DELETE = 'httpDELETE'; const HTTP_TIMEOUT_DEF = 30000; const HTTP_TIMEOUT_AWP = 3000; } class Exchange implements iExchange { private const CP_WIN1251 = 'WINDOWS-1251', CP_UTF8 = 'UTF-8'; private const ERR_SETTINGS = 'Проверьте настройку параметров соединения с ЦОД!', ERR_MSG_SEND_FAIL = 'обращение к серверу не выполнялось'; private const ERR_CODE_TOKEN = 497, ERR_CODE_SEND = 498, ERR_CODE_SEND_FAIL = 499; private const VALID_CODES = [200, 201, 202]; protected $link; protected $error_message; protected $expires_in; public function __construct(Link $link) { $this->link = $link; } public function getLink(): ?Link { return $this->link; } public function testConnection(?\stdClass $params = null): string { $link = $this->getLink(); $ls = $link->getLs(); if (empty($ls->getAllowedLink())) { return self::ERR_SETTINGS; } $this->getAccessToken($params); if (empty($link->getAccessToken())) { return "{$link->getAnswerCode()}: НЕ удалось получить ключ авторизации для доступа к ЦОД!\n\r {$this->error_message}"; } $result = $this->send($this->createParamTestConnection($params)); if (empty($result[1]) || !self::validResult($result[0] ?? 0)) { $str = $this->expandDPCerror($result[1] ?? ''); return "Ключ авторизации получен, НО при соединении с сервером ЦОД произошла ошибка {$link->getAnswerCode()}! {$str}"; } return ''; } private function createParamTestConnection(?\stdClass $params = null): ParamsHTTP { $link = $this->getLink(); $httpParams = new ParamsHTTP(); $httpParams->url = ($params->urlDPC ?? $link->getLs()->getParam('urlDPC')) . 'metadata?_format=json'; $httpParams->method = self::HTTP_GET; $httpParams->token = $link->getAccessToken(); return $httpParams; } public function getAccessToken(?\stdClass $params = null): bool { $link = $this->getLink(); $link->setAccessToken(''); $logMsg = Link::DEBUG ? " для {$link->getAccessScope()}" : ''; $link->getLogger()->addLog("запрос ключа доступа{$logMsg}"); $result = $this->send($this->createParamAccessToken($params)); return $this->checkAccessToken($result); } private function createParamAccessToken(?\stdClass $params = null): ParamsHTTP { $link = $this->getLink(); $ls = $link->getLs(); $httpParams = new ParamsHTTP(); $httpParams->url = $params->urlPDCauth ?? $ls->getParam('urlDPCauth'); $httpParams->method = self::HTTP_POST; $httpParams->content = self::RT_APPLICATION_X_WWW_FORM_URLENCODED; $httpParams->accept = self::RT_APPLICATION_JSON; $httpParams->timeout = $link->getCurrentTimeOut(); $httpParams->setRequestForm([ 'grant_type' => 'client_credentials', 'client_id' => $params->clientId ?? $ls->getParam('clientId'), 'client_secret' => $params->clientSecret ?? $ls->getParam('clientSecret'), 'scope' => $link->getAccessScope() ]); return $httpParams; } private function checkAccessToken(array $response): bool { $this->error_message = ''; $this->expires_in = 0; $link = $this->getLink(); $logger = $link->getLogger(); $link->setAccessToken(''); if ($response && isset($response[1])) { $answer = $this->decodeAccessToken($response[1]); if (empty($answer)) { $this->error_message = 'JSON->token: FALSE'; if (self::validResult($response[0])) { $link->setAnswerCode(self::ERR_CODE_TOKEN); } } else { $link->setAccessToken($answer->access_token ?? ''); $this->error_message = $answer->error ?? ''; $this->expires_in = $answer->expires_in ?? 0; } } if (empty($link->getAccessToken())) { $logger->addLog("! ключ доступа НЕ получен\t{$link->getAnswerCode()} {$this->error_message}"); } else { $link->setAccessTimeLimit(microtime(true) + ($this->expires_in - 10) * 1000); } return !empty($link->getAccessToken()); } private function decodeAccessToken(string $response): ?\stdClass { try { $token = safe_json_decode($response); if (empty($token)) { return null; } if (!$this->validateKeysJSON(['access_token'], $token)) { return null; } return $token; } catch (\Exception $exc) { return null; } } private function validateKeysJSON(array $keys, \stdClass $json): bool { try { foreach ($keys as $key) { if (!array_key_exists($key, (array) $json)) { return false; } } return true; } catch (\Exception $e) { return false; } } public function rfc(string $url, string $method = self::HTTP_GET, string $json = '', string $token = '', string $dataType = self::RT_APPLICATION_JSON_FHIR, int $timeOut = 0): array { $params = new ParamsHTTP(); $params->url = $url; $params->method = $method; $params->token = empty($token) ? $this->getLink()->getAccessToken() : $token; $params->setRequestContent($json); $params->content = $dataType; $params->timeout = $timeOut; return $this->send($params); } private function send(ParamsHTTP $params): array { $link = $this->getLink(); $logger = $link->getLogger(); $ls = $link->getLs(); $saveRequest = $ls->getParam('saveRequest'); $http = $params->method; $params->setHeader('Accept', empty($params->accept) ? $params->content : $params->accept); $params->setHeader('Content-Type', $params->content); $params->setProxy($ls); empty($params->timeout) && $params->timeout = $link->getDefaultTimeOut(); if (isset($params->token)) { $params->setHeader('Authorization', "Bearer {$params->token}"); } if ($saveRequest) { Link::DEBUG && $params->request_content && $logger->addLog($params->request_content, 'body', Logger::LMT_DEBUG); $token = isset($params->token) ? '+token' : ''; $logger->addLog($params->url, "{$params->method}{$token}", Logger::LMT_DEBUG); } $params->cleanParams(); try { $result = $http($params); if ($result && !empty($result['status'])) { $saveRequest && $logger->addLog("код ответа {$result['status'][1]}", 'TRUE', Logger::LMT_DEBUG); return $this->makeResponse($result['status'][1], $result['body']); } $saveRequest && $logger->addLog('запрос НЕ прошел', 'FALSE', Logger::LMT_DEBUG); return $this->makeResponse(self::ERR_CODE_SEND_FAIL, self::ERR_MSG_SEND_FAIL); } catch (\Exception $exc) { $msg = $exc->getMessage(); $saveRequest && $logger->addLog("EXCEPTION {$msg}", 'FALSE', Logger::LMT_DEBUG); return $this->makeResponse(self::ERR_CODE_SEND, $msg); } } private function makeResponse(int $code, string $message): array { $this->getLink()->setAnswerCode($code); return [ $code, $message ]; } private function expandDPCerror(string $response): string { if (empty($response)) { return ' нет ответа от сервера'; } $answer = safe_json_decode($response); if (empty($answer)) { return $response; } else { $ret = ''; foreach ($answer as $key) { if ($key === 'issue' && isset($key->details)) { $ret .= (empty($ret) ? '' : ' ') . $key->details['value']; } } } return ''; } public function validResult(int $code): bool { return \in_array($code, self::VALID_CODES); } public function getErrorMessage(): string { return $this->error_message; } public function getJSONResult(array $response, string $description = '', $exit = false): ?\stdClass { if (empty($response[1]) || !$this->validResult($response[0])) { $this->getLink()->getLogger()->addLog( "ошибка {$response[0]} $description" . (empty($description) ? '' : ' ') . $this->expandDPCerror($response[1]), '', Logger::LMT_ERROR, $exit); } return safe_json_decode(removeBOM($response[1])); } } 